import dspy
from dspy.teleprompt import BetterTogether
from dspy.teleprompt.teleprompt import Teleprompter
from dspy.utils.dummies import DummyLM


class SimpleModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predictor = dspy.Predict("input -> output")

    def forward(self, **kwargs):
        return self.predictor(**kwargs)


class PromptOptimizer(Teleprompter):
    def __init__(self):
        self.received_kwargs = None

    def compile(self, student, trainset=None, num_trials=None, **kwargs):
        self.received_kwargs = {"trainset": trainset, "num_trials": num_trials, **kwargs}
        return student


class WeightOptimizer(Teleprompter):
    def __init__(self):
        self.received_kwargs = None

    def compile(self, student, trainset=None, num_batches=None, **kwargs):
        self.received_kwargs = {"trainset": trainset, "num_batches": num_batches, **kwargs}
        return student


def metric(example, prediction, trace=None):
    return 1.0


student = SimpleModule()
student.set_lm(DummyLM([{"output": "out"}]))
trainset = [dspy.Example(input="train", output="out").with_inputs("input")]
valset = [dspy.Example(input="val", output="out").with_inputs("input")]
prompt_opt = PromptOptimizer()
weight_opt = WeightOptimizer()
optimizer = BetterTogether(metric=metric, p=prompt_opt, w=weight_opt)

with patch("dspy.teleprompt.bettertogether.eval_candidate_program", return_value=Mock(score=0.85)):
    with patch("dspy.teleprompt.bettertogether.launch_lms"):
        with patch("dspy.teleprompt.bettertogether.kill_lms"):
            with patch.object(optimizer, "_models_changed", return_value=False):
                optimizer.compile(
                    student,
                    trainset=trainset,
                    valset=valset,
                    strategy="p -> w",
                    optimizer_compile_args={"p": {"num_trials": 10}, "w": {"num_batches": 5}},
                )

print("prompt_kwargs:", prompt_opt.received_kwargs)
print("weight_kwargs:", weight_opt.received_kwargs)
assert prompt_opt.received_kwargs == {"trainset": trainset, "num_trials": 10}
assert weight_opt.received_kwargs == {"trainset": trainset, "num_batches": 5}

try:
    optimizer.compile(
        student,
        trainset=trainset,
        valset=valset,
        strategy="p -> w",
        optimizer_compile_args={"p": {"num_batches": 99}},
    )
    raise AssertionError("invalid step-specific args should raise ValueError")
except ValueError as exc:
    assert "Invalid compile arguments for optimizer 'p'" in str(exc)
    assert "num_batches" in str(exc)
